const incrementDepartureBookedCount = `-- name: IncrementDepartureBookedCount :one
UPDATE service_package_departures d
SET booked_count = d.booked_count + $1,
    status = CASE
        WHEN eff.capacity IS NOT NULL AND d.booked_count + $1 >= eff.capacity
            THEN 'full'
        ELSE d.status
    END
FROM (SELECT d2.id, COALESCE(d2.capacity, sm.capacity) AS capacity
      FROM service_package_departures d2
      JOIN service_listing_meta sm ON sm.id = d2.package_meta_id
      WHERE d2.id = $2) eff
WHERE d.id = $2
  AND d.id = eff.id
  AND d.status = 'open'
  AND (eff.capacity IS NULL OR d.booked_count + $1 <= eff.capacity)
RETURNING d.id, d.package_meta_id, d.starts_on, d.ends_on, d.capacity, d.booked_count, d.status, d.created_at
`

type IncrementDepartureBookedCountParams struct {
	PartySize int32       `json:"party_size"`
	ID        pgtype.UUID `json:"id"`
}

// Atomic capacity check + increment + 'full' flip. Returns no rows when
// the departure is not open or lacks capacity → service layer maps to
// ErrDepartureFull (§111: 409 departure_full). §111 schema: a NULL
// departure capacity inherits the package-level capacity (meta.capacity);
// both NULL means unlimited.
func (q *Queries) IncrementDepartureBookedCount(ctx context.Context, arg IncrementDepartureBookedCountParams) (ServicePackageDeparture, error) {
	row := q.db.QueryRow(ctx, incrementDepartureBookedCount, arg.PartySize, arg.ID)
	var i ServicePackageDeparture
	err := row.Scan(
		&i.ID,
		&i.PackageMetaID,
		&i.StartsOn,
		&i.EndsOn,
		&i.Capacity,
		&i.BookedCount,
		&i.Status,
		&i.CreatedAt,
	)
	return i, err
}

